import React, { useState } from 'react';
import '../styles/sidebar.css';

function Sidebar({ isOpen, onPlanRoute }) {
    const depVar  =  useState('');
    const destVar  =  useState('');
    const waypointsVar  =  useState([]);
    const dragStateVar  =  useState(null);

    const departure  =  depVar[0];
    const setDeparture  =  depVar[1];
    const destination  =  destVar[0];
    const setDestination  =  destVar[1];
    const waypoints  =  waypointsVar[0];
    const setWaypoints  =  waypointsVar[1];
    const dragState  =  dragStateVar[0];
    const setDragState  =  dragStateVar[1];

    const HandlePlanRoute  =  () => {
        if (departure.trim() && destination.trim()) {
            onPlanRoute({
                departure:  departure,
                destination:  destination,
                waypoints:  waypoints.filter(wp  =>  wp.name.trim())
            });
        }
    };

    const HandleAddWaypoint  =  () => {
        if (waypoints.length  <  5) {
            const newWaypoints  =  [...waypoints];
            newWaypoints.push({ id:  Date.now(), name:  '' });
            setWaypoints(newWaypoints);
        }
    };

    const HandleRemoveWaypoint  =  (id) => {
        const newWaypoints  =  waypoints.filter(wp  =>  wp.id  !==  id);
        setWaypoints(newWaypoints);
    };

    const HandleWaypointChange  =  (id, value) => {
        const newWaypoints  =  waypoints.map(wp  =>
            wp.id  ===  id  ?  { ...wp, name:  value }  :  wp
        );
        setWaypoints(newWaypoints);
    };

    const HandleDragStart  =  (e, index) => {
        setDragState(index);
        e.dataTransfer.effectAllowed  =  'move';
    };

    const HandleDragOver  =  (e, index) => {
        e.preventDefault();
        e.dataTransfer.dropEffect  =  'move';
    };

    const HandleDrop  =  (e, dropIndex) => {
        e.preventDefault();
        if (dragState  !==  null && dragState  !==  dropIndex) {
            const newWaypoints  =  [...waypoints];
            const draggedItem  =  newWaypoints[dragState];
            newWaypoints.splice(dragState, 1);
            newWaypoints.splice(dropIndex, 0, draggedItem);
            setWaypoints(newWaypoints);
        }
        setDragState(null);
    };

    const HandleDragEnd  =  () => {
        setDragState(null);
    };

    const HandleChange  =  (e, setter) => {
        setter(e.target.value);
    };

    return (
        <aside className  =  {`sidebar ${isOpen  ?  'open'  :  'closed'}`}>
            <div className  =  "sidebar-content">
                <h2>行程规划</h2>
                <div className  =  "route-input-group">
                    <label htmlFor  =  "departure-input">出发地</label>
                    <input
                        id  =  "departure-input"
                        type  =  "text"
                        placeholder  =  "输入出发地名称"
                        value  =  {departure}
                        onChange  =  {(e)  =>  HandleChange(e, setDeparture)}
                        className  =  "route-input"
                    />
                </div>

                <div className  =  "waypoints-container">
                    {waypoints.map((wp, index)  =>  (
                        <div
                            key  =  {wp.id}
                            className  =  {`waypoint-item ${dragState  ===  index  ?  'dragging'  :  ''}`}
                            draggable
                            onDragStart  =  {(e)  =>  HandleDragStart(e, index)}
                            onDragOver  =  {(e)  =>  HandleDragOver(e, index)}
                            onDrop  =  {(e)  =>  HandleDrop(e, index)}
                            onDragEnd  =  {HandleDragEnd}
                        >
                            <div className  =  "waypoint-number">{index  +  1}</div>
                            <input
                                type  =  "text"
                                placeholder  =  {`途经点 ${index  +  1}`}
                                value  =  {wp.name}
                                onChange  =  {(e)  =>  HandleWaypointChange(wp.id, e.target.value)}
                                className  =  "waypoint-input"
                            />
                            <button
                                className  =  "waypoint-delete"
                                onClick  =  {()  =>  HandleRemoveWaypoint(wp.id)}
                            >
                                删除
                            </button>
                        </div>
                    ))}
                </div>

                {waypoints.length  <  5  &&  (
                    <button className  =  "add-waypoint-button" onClick  =  {HandleAddWaypoint}>
                        + 添加途经点
                    </button>
                )}

                <div className  =  "route-input-group">
                    <label htmlFor  =  "destination-input">目的地</label>
                    <input
                        id  =  "destination-input"
                        type  =  "text"
                        placeholder  =  "输入目的地名称"
                        value  =  {destination}
                        onChange  =  {(e)  =>  HandleChange(e, setDestination)}
                        className  =  "route-input"
                    />
                </div>

                <button className  =  "plan-button" onClick  =  {HandlePlanRoute}>
                    规划路线
                </button>
            </div>
        </aside>
    );
}

export default Sidebar;

