import React, { useEffect, useRef } from 'react';
import '../styles/maparea.css';

function Maparea({ routeData }) {
    const mapContainer  =  useRef(null);
    const mapInstance  =  useRef(null);
    const markersRef  =  useRef([]);
    const polylinesRef  =  useRef([]);

    useEffect(() => {
        if (!mapContainer.current || mapInstance.current) {
            return;
        }

        const map  =  window.L.map(mapContainer.current).setView([39.9042, 116.4074], 13);
        mapInstance.current  =  map;

        window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            maxZoom:  19,
            attribution:  '© OpenStreetMap contributors'
        }).addTo(map);

        map.on('click', HandleMapClick);

        return () => {
            if (map) {
                map.off('click', HandleMapClick);
            }
        };
    }, []);

    useEffect(() => {
        if (routeData && mapInstance.current) {
            HandlePlanRoute(routeData);
        }
    }, [routeData]);

    const HandleMapClick  =  (e) => {
        const { lat, lng }  =  e.latlng;
        const marker  =  window.L.marker([lat, lng], {
            title:  `${lat.toFixed(4)}, ${lng.toFixed(4)}`
        }).addTo(mapInstance.current);

        const popup  =  window.L.popup()
            .setLatLng([lat, lng])
            .setContent(`<div class  =  "popup-content"><strong>坐标</strong><br/>纬度: ${lat.toFixed(6)}<br/>经度: ${lng.toFixed(6)}</div>`);

        marker.bindPopup(popup).openPopup();
        markersRef.current.push(marker);
    };

    const CreateCustomIcon  =  (number) => {
        const svgIcon  =  `
            <svg width="30" height="30" viewBox="0 0 30 30" xmlns="http://www.w3.org/2000/svg">
                <circle cx="15" cy="15" r="12" fill="#FF9800" stroke="white" stroke-width="2"/>
                <text x="15" y="18" text-anchor="middle" font-size="14" font-weight="bold" fill="white">${number}</text>
            </svg>
        `;
        const encoded  =  encodeURIComponent(svgIcon);
        return window.L.icon({
            iconUrl:  `data:image/svg+xml,${encoded}`,
            iconSize:  [30, 30],
            iconAnchor:  [15, 15],
            popupAnchor:  [0, -15]
        });
    };

    const HandlePlanRoute  =  (data) => {
        ClearRoute();

        const startLat  =  39.9042;
        const startLng  =  116.4074;
        const endLat  =  39.8686;
        const endLng  =  116.5516;

        const startMarker  =  window.L.marker([startLat, startLng], {
            icon:  window.L.icon({
                iconUrl:  'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-2x-green.png',
                shadowUrl:  'https://cdnjs.cloudflare.com/ajax/libs/leaflet/0.7.7/images/marker-shadow.png',
                iconSize:  [25, 41],
                iconAnchor:  [12, 41],
                popupAnchor:  [1, -34],
                shadowSize:  [41, 41]
            })
        }).addTo(mapInstance.current);

        const startPopup  =  window.L.popup()
            .setLatLng([startLat, startLng])
            .setContent(`<div class  =  "popup-content"><strong>出发地: ${data.departure}</strong><br/>纬度: ${startLat.toFixed(6)}<br/>经度: ${startLng.toFixed(6)}</div>`);
        startMarker.bindPopup(startPopup);

        const waypointCoords  =  [];
        const waypoints  =  data.waypoints || [];

        waypoints.forEach((wp, index) => {
            const offset  =  0.02;
            const wpLat  =  startLat  +  (endLat  -  startLat)  *  ((index  +  1)  /  (waypoints.length  +  1));
            const wpLng  =  startLng  +  (endLng  -  startLng)  *  ((index  +  1)  /  (waypoints.length  +  1))  +  offset  *  (index  %  2  ===  0  ?  1  :  -1);
            waypointCoords.push([wpLat, wpLng]);

            const wpMarker  =  window.L.marker([wpLat, wpLng], {
                icon:  CreateCustomIcon(index  +  1)
            }).addTo(mapInstance.current);

            const wpPopup  =  window.L.popup()
                .setLatLng([wpLat, wpLng])
                .setContent(`<div class  =  "popup-content"><strong>途经点 ${index  +  1}: ${wp.name}</strong><br/>纬度: ${wpLat.toFixed(6)}<br/>经度: ${wpLng.toFixed(6)}</div>`);
            wpMarker.bindPopup(wpPopup);
            markersRef.current.push(wpMarker);
        });

        const endMarker  =  window.L.marker([endLat, endLng], {
            icon:  window.L.icon({
                iconUrl:  'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-2x-red.png',
                shadowUrl:  'https://cdnjs.cloudflare.com/ajax/libs/leaflet/0.7.7/images/marker-shadow.png',
                iconSize:  [25, 41],
                iconAnchor:  [12, 41],
                popupAnchor:  [1, -34],
                shadowSize:  [41, 41]
            })
        }).addTo(mapInstance.current);

        const endPopup  =  window.L.popup()
            .setLatLng([endLat, endLng])
            .setContent(`<div class  =  "popup-content"><strong>目的地: ${data.destination}</strong><br/>纬度: ${endLat.toFixed(6)}<br/>经度: ${endLng.toFixed(6)}</div>`);
        endMarker.bindPopup(endPopup);

        markersRef.current.push(startMarker);
        markersRef.current.push(endMarker);

        const pathCoords  =  [[startLat, startLng], ...waypointCoords, [endLat, endLng]];
        const polyline  =  window.L.polyline(pathCoords, { color:  '#2196F3', weight:  3, opacity:  0.8 }).addTo(mapInstance.current);
        polylinesRef.current.push(polyline);

        const allMarkers  =  [startMarker, endMarker, ...markersRef.current];
        const featureGroup  =  window.L.featureGroup(allMarkers);
        mapInstance.current.fitBounds(featureGroup.getBounds().pad(0.1));
    };

    const ClearRoute  =  () => {
        markersRef.current.forEach(marker => {
            mapInstance.current.removeLayer(marker);
        });
        polylinesRef.current.forEach(polyline => {
            mapInstance.current.removeLayer(polyline);
        });
        markersRef.current  =  [];
        polylinesRef.current  =  [];
    };

    return (
        <main className  =  "map-area">
            <div ref  =  {mapContainer} className  =  "map-container"></div>
        </main>
    );
}

export default Maparea;
